'use client';
import Link from 'next/link';
import { useLanguage } from '../lib/LanguageContext';

export default function Footer() {
  const { t } = useLanguage();
  const currentYear = new Date().getFullYear();

  return (
    <footer className="site-footer">
      <div className="container footer-main">
        
        <div className="footer-brand">
          <Link href="/" className="footer-brand-link">
            <img src="/logo-icon.png" alt="VeriWork Icon" className="logo-img" />
            <span>VeriWork</span>
          </Link>
          <p className="footer-desc">{t('footer.desc')}</p>
        </div>

        <nav aria-label="Product">
          <h2 className="footer-title">{t('footer.product')}</h2>
          <ul className="footer-links">
            <li><Link href="#digital-card">{t('footer.features')}</Link></li>
            <li><Link href="#pricing">{t('footer.pricing')}</Link></li>
            <li><Link href="#trust-score">{t('nav.trust')}</Link></li>
            <li><Link href="#employers">{t('footer.employers')}</Link></li>
          </ul>
        </nav>

        <nav aria-label="Company">
          <h2 className="footer-title">{t('footer.company')}</h2>
          <ul className="footer-links">
            <li><Link href="#about">{t('footer.about')}</Link></li>
            <li><Link href="#careers">{t('footer.careers')}</Link></li>
            <li><Link href="#blog">{t('footer.blog')}</Link></li>
            <li><Link href="#contact">{t('footer.contact')}</Link></li>
          </ul>
        </nav>

        <nav aria-label="Legal">
          <h2 className="footer-title">{t('footer.legal')}</h2>
          <ul className="footer-links">
            <li><Link href="#privacy">{t('footer.privacy')}</Link></li>
            <li><Link href="#terms">{t('footer.terms')}</Link></li>
            <li><Link href="#cookies">{t('footer.cookies')}</Link></li>
          </ul>
        </nav>

      </div>

      <div className="footer-bottom">
        <div className="container footer-bottom-inner">
          <p className="footer-copy">
            &copy; <span>{currentYear}</span> VeriWork. <span>{t('footer.rights')}</span>
          </p>
          <nav className="footer-social" aria-label={t('footer.social')}>
            <Link href="#linkedin">LinkedIn</Link>
            <Link href="#twitter">Twitter</Link>
            <Link href="#facebook">Facebook</Link>
          </nav>
        </div>
      </div>
    </footer>
  );
}