'use client';
import Link from 'next/link';
import { useState, useEffect } from 'react';
import { useLanguage } from '../lib/LanguageContext';

export default function Navbar() {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);
  const [theme, setTheme] = useState('light');
  
  // Gọi hàm dịch và đổi ngôn ngữ từ Context
  const { language, changeLanguage, t, LANGUAGES } = useLanguage();

  useEffect(() => {
    // Khởi tạo theme từ localStorage khi load trang
    const savedTheme = localStorage.getItem('veriwork-theme') || 'light';
    setTheme(savedTheme);
    document.body.setAttribute('data-theme', savedTheme);
  }, []);

  const toggleTheme = () => {
    const nextTheme = theme === 'dark' ? 'light' : 'dark';
    setTheme(nextTheme);
    localStorage.setItem('veriwork-theme', nextTheme);
    document.body.setAttribute('data-theme', nextTheme);
  };

  const handleLanguageSelect = (code) => {
    changeLanguage(code);
    setIsLangMenuOpen(false); // Ẩn menu đi sau khi chọn xong
  };

  return (
    <header className="site-header">
      <div className="container">
        <div className="header-inner">
          
          {/* Logo */}
          <Link href="/" className="logo">
            <img src="/logo-icon.png" alt="VeriWork Icon" className="logo-img" />
            <span>VeriWork</span>
          </Link>

          {/* Main Navigation (Chỉ hiện trên Desktop) */}
          <nav className="main-nav" aria-label="Primary">
            <ul className="nav-list">
              <li><Link className="nav-link" href="/" aria-current="page">{t('nav.home')}</Link></li>
              <li><Link className="nav-link" href="#projects">{t('nav.projects')}</Link></li>
              <li><Link className="nav-link" href="#services">{t('nav.services')}</Link></li>
              <li><Link className="nav-link" href="#students">{t('nav.students')}</Link></li>
              <li><Link className="nav-link" href="#trust-score">{t('nav.trust')}</Link></li>
            </ul>
          </nav>

          {/* Actions (Chỉ hiện trên Desktop) */}
          <div className="header-actions">
            <Link className="btn btn-ghost" href="/login">{t('auth.login')}</Link>
            
            {/* Bộ chọn ngôn ngữ */}
            <div className="lang-switch">
              <button 
                type="button" 
                className="lang-btn" 
                aria-expanded={isLangMenuOpen}
                onClick={() => setIsLangMenuOpen(!isLangMenuOpen)}
              >
                <svg className="icon-globe" viewBox="0 0 24 24" aria-hidden="true">
                  <circle cx="12" cy="12" r="9"/>
                  <path d="M3 12h18M12 3c2.5 2.7 3.8 5.7 3.8 9s-1.3 6.3-3.8 9c-2.5-2.7-3.8-5.7-3.8-9S9.5 5.7 12 3z"/>
                </svg>
                <span className="lang-code">{language.toUpperCase()}</span>
              </button>
              
              {isLangMenuOpen && (
                <ul className="lang-menu" role="listbox">
                  {LANGUAGES.map((l) => (
                    <li key={l.code} role="presentation">
                      <button 
                        type="button" 
                        className="lang-option"
                        role="option"
                        aria-selected={language === l.code}
                        onClick={() => handleLanguageSelect(l.code)}
                      >
                        {l.name}
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </div>

            {/* Nút đổi Sáng / Tối */}
            <button 
              type="button" 
              className="theme-toggle" 
              aria-label="Switch theme"
              onClick={toggleTheme}
            >
              <svg className="icon-moon" viewBox="0 0 24 24" aria-hidden="true">
                <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>
              </svg>
              <svg className="icon-sun" viewBox="0 0 24 24" aria-hidden="true">
                <circle cx="12" cy="12" r="5"/>
                <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/>
              </svg>
            </button>

            <Link className="btn btn-primary" href="/signup">{t('auth.signup')}</Link>
          </div>

          {/* Nút điều khiển Menu (Chỉ hiện trên Mobile) */}
          <div className="mobile-controls">
            <button 
              id="menu-btn" 
              className="menu-toggle" 
              type="button"
              aria-expanded={isMobileMenuOpen}
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            >
              {isMobileMenuOpen ? t('nav.close') : t('nav.menu')}
            </button>
          </div>
        </div>
      </div>

      {/* Bảng Menu Mobile */}
      {isMobileMenuOpen && (
        <div id="mobile-menu" className="mobile-menu">
          <div className="mobile-menu-card">
            <nav aria-label="Mobile">
              <ul className="mobile-nav-list">
                <li><Link className="mobile-nav-link" href="/" onClick={() => setIsMobileMenuOpen(false)}>{t('nav.home')}</Link></li>
                <li><Link className="mobile-nav-link" href="#projects" onClick={() => setIsMobileMenuOpen(false)}>{t('nav.projects')}</Link></li>
                <li><Link className="mobile-nav-link" href="#services" onClick={() => setIsMobileMenuOpen(false)}>{t('nav.services')}</Link></li>
                <li><Link className="mobile-nav-link" href="#students" onClick={() => setIsMobileMenuOpen(false)}>{t('nav.students')}</Link></li>
                <li><Link className="mobile-nav-link" href="#trust-score" onClick={() => setIsMobileMenuOpen(false)}>{t('nav.trust')}</Link></li>
              </ul>
            </nav>
            <div className="mobile-actions">
              <Link className="btn btn-ghost" href="/login" onClick={() => setIsMobileMenuOpen(false)}>{t('auth.login')}</Link>
              <Link className="btn btn-primary" href="/signup" onClick={() => setIsMobileMenuOpen(false)}>{t('auth.signup')}</Link>
            </div>
          </div>
        </div>
      )}
    </header>
  );
}